<?php
declare(strict_types=1);

final class MothershipExplorationService
{
    private const RARITY=['temperate'=>1.00,'forest'=>1.05,'jungle'=>1.10,'oceanic'=>1.12,'arid'=>1.08,'desert'=>1.15,'tundra'=>1.18,'ice'=>1.20,'volcanic'=>1.25,'toxic'=>1.30,'crystal'=>1.45,'metallic'=>1.40,'gas'=>1.08,'barren'=>1.02,'ancient'=>1.60];
    public function __construct(private PDO $pdo) {}
    private function setting(string $key,int $default=0):int{$s=$this->pdo->prepare('SELECT setting_value FROM game_settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:max(0,(int)$v);}
    private function event(int $playerId,int $planetId,array $payload):void{$s=$this->pdo->prepare('INSERT INTO game_events(player_id,event_type,entity_type,entity_id,payload) VALUES(?,?,?,?,?)');$s->execute([$playerId,'mothership_exploration','universe_planet',$planetId,json_encode($payload,JSON_THROW_ON_ERROR)]);}
    private function target(int $planetId):?array{$s=$this->pdo->prepare('SELECT p.*,ss.system_number,ss.travel_modifier,ss.system_class FROM universe_planets p JOIN universe_solar_systems ss ON ss.id=p.solar_system_id WHERE p.id=?');$s->execute([$planetId]);$r=$s->fetch(PDO::FETCH_ASSOC);return $r?:null;}
    public function snapshot(int $playerId):array
    {
        if($playerId<1)throw new InvalidArgumentException('Invalid exploration request.');$ship=$this->pdo->prepare('SELECT id,hull_level,exploration_level,fleet_hangars FROM motherships WHERE player_id=?');$ship->execute([$playerId]);$m=$ship->fetch(PDO::FETCH_ASSOC);$states=['ready','protected','insufficient-resource','cooldown','success','error'];if(!$m)return ['state'=>'locked','mothership'=>null,'expeditions'=>[],'formula'=>'exploration yield = distance × ship science × biome rarity','states'=>$states];$s=$this->pdo->query("SELECT p.id,p.name,p.coordinate_label,p.biome,p.planet_class,p.planet_type,p.is_occupied,p.anomaly_rate,ss.system_number,ss.travel_modifier,ss.system_class FROM universe_planets p JOIN universe_solar_systems ss ON ss.id=p.solar_system_id WHERE p.is_occupied=0 ORDER BY p.id LIMIT 30");$rows=$s->fetchAll(PDO::FETCH_ASSOC);$science=max(1,(int)$m['exploration_level']+(int)$m['fleet_hangars']);foreach($rows as &$r){$distance=max(1,((int)$r['system_number']*10)+(int)$r['id']%10);$rarity=self::RARITY[$r['biome']]??1.0;$r['distance']=$distance;$r['ship_science']=$science;$r['biome_rarity']=$rarity;$r['estimated_yield']=(int)round($distance*$science*$rarity);$r['travel_seconds']=(int)max(60,round($distance*60*(float)$r['travel_modifier']));$r['discovery_risk']=round(min(0.95,max(0.01,(float)$r['anomaly_rate']+(($r['system_class']==='anomalous')?0.10:0))),3);}unset($r);return ['state'=>'ready','mothership'=>['id'=>(int)$m['id'],'hull_level'=>(int)$m['hull_level'],'exploration_level'=>(int)$m['exploration_level'],'fleet_hangars'=>(int)$m['fleet_hangars'],'ship_science'=>$science,'ready'=>((int)$m['hull_level']>0)],'expeditions'=>$rows,'formula'=>'exploration yield = distance × ship science × biome rarity','states'=>$states];
    }
    public function explore(int $playerId,int $planetId):array
    {
        if($playerId<1||$planetId<1)throw new InvalidArgumentException('Invalid exploration target.');$this->pdo->beginTransaction();try{$cooldown=$this->setting('mothership_explore_cooldown_seconds',300);$c=$this->pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='mothership_explore' FOR UPDATE");$c->execute([$playerId]);$available=$c->fetchColumn();if($available!==false&&new DateTimeImmutable((string)$available)>new DateTimeImmutable('now'))throw new RuntimeException('Mothership exploration is on cooldown.');$s=$this->pdo->prepare('SELECT id,hull_level,exploration_level,fleet_hangars FROM motherships WHERE player_id=? FOR UPDATE');$s->execute([$playerId]);$m=$s->fetch(PDO::FETCH_ASSOC);if(!$m||((int)$m['hull_level']<1))throw new RuntimeException('Mothership is not ready.');$p=$this->pdo->prepare('SELECT p.*,ss.system_number,ss.travel_modifier,ss.system_class FROM universe_planets p JOIN universe_solar_systems ss ON ss.id=p.solar_system_id WHERE p.id=? FOR UPDATE');$p->execute([$planetId]);$planet=$p->fetch(PDO::FETCH_ASSOC);if(!$planet)throw new RuntimeException('Exploration target not found.');if((int)$planet['is_occupied'])throw new RuntimeException('Exploration target is occupied.');$science=max(1,(int)$m['exploration_level']+(int)$m['fleet_hangars']);$distance=max(1,((int)$planet['system_number']*10)+(int)$planet['id']%10);$rarity=self::RARITY[$planet['biome']]??1.0;$yield=(int)round($distance*$science*$rarity);$travel=(int)max(60,round($distance*60*(float)$planet['travel_modifier']));$risk=round(min(0.95,max(0.01,(float)$planet['anomaly_rate']+(($planet['system_class']==='anomalous')?0.10:0))),3);$cost=25000;$r=$this->pdo->prepare('SELECT naquadah FROM player_resources WHERE player_id=? FOR UPDATE');$r->execute([$playerId]);if((int)$r->fetchColumn()<$cost)throw new RuntimeException('Not enough Naquadah.');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$reward=$risk>=0.5?'anomaly_data':($yield>=100?'rare_resources':'exploration_intelligence');$payload=['target_planet_id'=>$planetId,'coordinate'=>$planet['coordinate_label'],'distance'=>$distance,'ship_science'=>$science,'biome'=>$planet['biome'],'biome_rarity'=>$rarity,'yield'=>$yield,'travel_seconds'=>$travel,'discovery_risk'=>$risk,'reward'=>$reward,'cost'=>$cost];$this->pdo->prepare("INSERT INTO planet_explorations(player_id,name,discovery_type,status,result_json,completed_at) VALUES(?,?,?,'completed',?,NOW())")->execute([$playerId,$planet['name'],'mothership_exploration',json_encode($payload,JSON_THROW_ON_ERROR)]);$id=(int)$this->pdo->lastInsertId();if($cooldown>0){$next=(new DateTimeImmutable('now'))->modify('+'.$cooldown.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,'mothership_explore',$next]);}$this->event($playerId,$planetId,['exploration_id'=>$id,'yield'=>$yield,'travel_seconds'=>$travel,'discovery_risk'=>$risk,'reward'=>$reward,'cost'=>$cost,'cooldown_seconds'=>$cooldown]);$this->pdo->commit();return ['state'=>'success','exploration_id'=>$id,'planet_id'=>$planetId,'target'=>$planet['name'],'yield'=>$yield,'travel_seconds'=>$travel,'discovery_risk'=>$risk,'reward'=>$reward,'cost'=>$cost,'cooldown_seconds'=>$cooldown];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
}
